-- Cyprus deep-dive ES/DE/FR translations (completing 249). INSERT OR IGNORE.

INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'es', 'Emisión B2G voluntaria, sin mandato B2B — obligación de recepción solo desde 2020', 'Esta página de análisis refleja la orientación pública y las noticias disponibles a principios de agosto de 2026 y se proporciona a título informativo general, no como asesoramiento legal o fiscal. Chipre no tiene un calendario confirmado para un mandato nacional de facturación electrónica B2B ni de emisión B2G en el momento de redactar esto — confirme el estado actual directamente con el Ministerio de Hacienda antes de basarse en ella.', 'Chipre completó un modesto despliegue de facturación electrónica B2G, solo de recepción, en abril de 2020 y, desde entonces, ha discutido repetidamente — pero nunca promulgado — un mandato para que los proveedores realmente emitan facturas electrónicas. Un objetivo del 1 de enero de 2022 para la emisión B2G obligatoria fue propuesto por el Ministerio de Hacienda y abandonado silenciosamente; un impulso similar para 2024 corrió la misma suerte. Ningún mandato B2B nacional ha tenido nunca una fecha confirmada. La única fecha firme en el horizonte de Chipre sigue siendo el suelo transfronterizo de ViDA de toda la UE, del 1 de julio de 2030.', 'Cuando las facturas electrónicas se intercambian de forma voluntaria, siguen la norma europea EN 16931, normalmente a través de la red Peppol o del propio portal del gobierno — no existe un formato nacional chipriota independiente.', 'La única obligación exigible en Chipre hoy en día va en una sola dirección: los organismos del sector público (centrales desde 2019, todos los demás organismos públicos desde 2020) deben poder recibir y procesar facturas electrónicas conformes. Nada obliga a un proveedor a enviar realmente una — la facturación B2G hoy se realiza en papel, mediante factura electrónica voluntaria, o según cualquier acuerdo bilateral que una empresa y su contraparte gubernamental decidan.', 'Sin ningún mandato nacional — de emisión B2G o B2B — actualmente vigente o previsto, el trabajo relevante de la mayoría de las empresas se limita a la preparación más que al cumplimiento: entender que la obligación de recepción existe en el lado gubernamental, y prepararse para la única fecha que está confirmada con independencia de las propias decisiones nacionales de Chipre.', 'No existe hoy un régimen sancionador de facturación electrónica nacional en Chipre, por la simple razón de que no existe un mandato nacional de facturación electrónica para los proveedores que puedan incumplir. La única obligación exigible recae en los organismos públicos, no en las empresas.', 'Chipre transpuso la Directiva 2014/55/UE de la UE mediante la Ley 89(I)/2019, exigiendo que los organismos públicos centrales reciban facturas electrónicas conformes con EN 16931 desde el 18 de abril de 2019, ampliado a todos los demás organismos públicos desde el 18 de abril de 2020. La emisión por parte de los proveedores ha seguido siendo voluntaria en todo momento. El Ministerio de Hacienda discutió hacer obligatoria la emisión B2G desde el 1 de enero de 2022, y de nuevo alrededor de 2024; ninguno de los dos objetivos se promulgó jamás, y ningún mandato B2B nacional tiene un calendario confirmado. Por separado, el mandato de ViDA de facturación electrónica y reporte transfronterizos B2B es derecho de la UE confirmado desde el 1 de julio de 2030, con independencia de cualquier futura decisión nacional chipriota.', '🇨🇾' FROM countries WHERE name_en = 'Cyprus';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'de', 'Freiwillige B2G-Ausstellung, keine B2B-Pflicht — reine Empfangspflicht seit 2020', 'Diese Länderanalyse spiegelt öffentlich verfügbare Hinweise und Berichterstattung mit Stand Anfang August 2026 wider und dient der allgemeinen Information, nicht als Rechts- oder Steuerberatung. Zypern hat zum Zeitpunkt der Abfassung keinen bestätigten Zeitplan für eine inländische B2B- oder B2G-Ausstellungspflicht — bestätigen Sie den aktuellen Stand direkt beim Finanzministerium, bevor Sie darauf aufbauen.', 'Zypern schloss bis April 2020 eine bescheidene, reine Empfangspflicht für die B2G-E-Rechnung ab und hat seitdem wiederholt eine Pflicht für Lieferanten diskutiert — aber nie erlassen —, tatsächlich E-Rechnungen auszustellen. Ein für den 1. Januar 2022 vorgeschlagenes Ziel für die verpflichtende B2G-Ausstellung wurde vom Finanzministerium eingebracht und still fallengelassen; ein ähnlicher Vorstoß für 2024 erlitt dasselbe Schicksal. Keine inländische B2B-Pflicht hatte je ein bestätigtes Datum. Das einzig feste Datum am zypriotischen Horizont bleibt die EU-weite ViDA-Untergrenze für grenzüberschreitende Umsätze vom 1. Juli 2030.', 'Wo E-Rechnungen freiwillig ausgetauscht werden, folgen sie der europäischen Norm EN 16931, meist über das Peppol-Netzwerk oder das Regierungsportal — es gibt kein separates zypriotisches nationales Format.', 'Die einzige durchsetzbare Pflicht in Zypern verläuft heute in eine Richtung: Öffentliche Stellen (zentral seit 2019, alle übrigen öffentlichen Stellen seit 2020) müssen konforme E-Rechnungen empfangen und verarbeiten können. Nichts verpflichtet einen Lieferanten, tatsächlich eine zu versenden — B2G-Rechnungsstellung erfolgt heute auf Papier, per freiwilliger E-Rechnung, oder nach welcher bilateralen Vereinbarung auch immer ein Unternehmen und sein staatlicher Geschäftspartner treffen.', 'Da derzeit keine inländische Pflicht — für die B2G-Ausstellung oder für B2B — in Kraft oder geplant ist, beschränkt sich die relevante Arbeit der meisten Unternehmen auf Vorbereitung statt Compliance: verstehen, dass die Empfangspflicht auf staatlicher Seite besteht, und sich auf das eine Datum vorbereiten, das unabhängig von Zyperns eigenen inländischen Entscheidungen bestätigt ist.', 'Es gibt heute kein inländisches E-Rechnungs-Sanktionsregime in Zypern, aus dem einfachen Grund, dass es keine inländische E-Rechnungspflicht für Lieferanten gibt, gegen die verstoßen werden könnte. Die einzige durchsetzbare Pflicht liegt bei öffentlichen Stellen, nicht bei Unternehmen.', 'Zypern setzte die EU-Richtlinie 2014/55/EU mit dem Gesetz 89(I)/2019 um und verlangt seit dem 18. April 2019, dass zentrale öffentliche Stellen EN-16931-konforme E-Rechnungen empfangen, erweitert auf alle übrigen öffentlichen Stellen seit dem 18. April 2020. Die Ausstellung durch Lieferanten blieb durchgehend freiwillig. Das Finanzministerium diskutierte, die B2G-Ausstellung ab dem 1. Januar 2022 verpflichtend zu machen, und erneut um 2024; keines der beiden Ziele wurde je umgesetzt, und keine inländische B2B-Pflicht hat einen bestätigten Zeitplan. Unabhängig davon ist ViDAs grenzüberschreitende B2B-E-Rechnungs- und Meldepflicht ab dem 1. Juli 2030 bestätigtes EU-Recht, unabhängig von einer künftigen zypriotischen inländischen Entscheidung.', '🇨🇾' FROM countries WHERE name_en = 'Cyprus';
INSERT OR IGNORE INTO deep_dive_page_translations (country_id, lang, compliance_model, footer_disclaimer, timeline_intro, file_format_intro, scope_intro, steps_intro, penalties_intro, mandate_summary, mandate_summary_icon) SELECT id, 'fr', 'Émission B2G volontaire, aucune obligation B2B — obligation de réception uniquement depuis 2020', 'Cette analyse par pays reflète les informations publiques et l''actualité disponibles début août 2026 et est fournie à titre d''information générale, non comme un conseil juridique ou fiscal. Chypre n''a aucun calendrier confirmé pour une obligation nationale de facturation électronique B2B ou d''émission B2G au moment de la rédaction — confirmez le statut actuel directement auprès du ministère des Finances avant de vous y fier.', 'Chypre a achevé d''ici avril 2020 un déploiement modeste, uniquement en réception, de la facturation électronique B2G et a, depuis lors, discuté à plusieurs reprises — sans jamais l''adopter — d''une obligation pour les fournisseurs d''émettre effectivement des factures électroniques. Un objectif du 1er janvier 2022 pour l''émission B2G obligatoire a été proposé par le ministère des Finances puis discrètement abandonné ; une initiative similaire pour 2024 a connu le même sort. Aucune obligation B2B nationale n''a jamais eu de date confirmée. La seule date ferme à l''horizon chypriote reste le plancher transfrontalier ViDA à l''échelle de l''UE, au 1er juillet 2030.', 'Lorsque des factures électroniques sont échangées volontairement, elles suivent la norme européenne EN 16931, généralement via le réseau Peppol ou le portail du gouvernement lui-même — il n''existe aucun format national chypriote distinct.', 'La seule obligation exécutoire à Chypre aujourd''hui va dans un seul sens : les organismes du secteur public (centraux depuis 2019, tous les autres organismes publics depuis 2020) doivent pouvoir recevoir et traiter des factures électroniques conformes. Rien n''oblige un fournisseur à en envoyer réellement une — la facturation B2G se fait aujourd''hui sur papier, par facture électronique volontaire, ou selon tout arrangement bilatéral qu''une entreprise et sa contrepartie gouvernementale décident.', 'En l''absence de toute obligation nationale — d''émission B2G ou de B2B — actuellement en vigueur ou prévue, le travail pertinent de la plupart des entreprises se limite à la préparation plutôt qu''à la conformité : comprendre que l''obligation de réception existe côté gouvernemental, et se préparer à la seule date confirmée indépendamment des propres décisions nationales de Chypre.', 'Il n''existe aujourd''hui aucun régime de sanctions national de facturation électronique à Chypre, pour la simple raison qu''il n''existe aucune obligation nationale de facturation électronique pour les fournisseurs qui pourrait être enfreinte. La seule obligation exécutoire incombe aux organismes publics, non aux entreprises.', 'Chypre a transposé la directive européenne 2014/55/UE via la loi 89(I)/2019, exigeant que les organismes publics centraux reçoivent des factures électroniques conformes à l''EN 16931 depuis le 18 avril 2019, étendue à tous les autres organismes publics depuis le 18 avril 2020. L''émission par les fournisseurs est restée volontaire tout au long. Le ministère des Finances a envisagé de rendre l''émission B2G obligatoire à partir du 1er janvier 2022, puis à nouveau vers 2024 ; aucun des deux objectifs n''a jamais été adopté, et aucune obligation B2B nationale n''a de calendrier confirmé. Par ailleurs, l''obligation ViDA de facturation électronique et de déclaration transfrontalières B2B est un droit de l''UE confirmé à partir du 1er juillet 2030, indépendamment de toute future décision nationale chypriote.', '🇨🇾' FROM countries WHERE name_en = 'Cyprus';

