INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Formato y estándar', '[["Estándar", "EN 16931, la norma europea de facturación electrónica"], ["Base legal", "Ley 89(I)/2019, que transpone la Directiva 2014/55/UE de la UE"], ["Formato nacional", "Ninguno — no existe un formato chipriota independiente junto a EN 16931"], ["B2B hoy", "Sin mandato; acuerdo bilateral entre socios comerciales cuando se usa"]]', 'Aquí no hay ninguna decisión de formato que tomar como sí la hay en países con su propio estándar nacional — EN 16931 a través de Peppol es simplemente el enfoque aceptado dondequiera que se use la facturación electrónica de forma voluntaria.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Format & Standard', '[["Standard", "EN 16931, die europäische Norm für E-Rechnung"], ["Rechtsgrundlage", "Gesetz 89(I)/2019, Umsetzung der EU-Richtlinie 2014/55/EU"], ["Nationales Format", "Keines — es gibt kein separates zypriotisches Format neben EN 16931"], ["B2B heute", "Keine Pflicht; bilaterale Vereinbarung zwischen Handelspartnern, sofern überhaupt genutzt"]]', 'Es gibt hier keine Formatentscheidung zu treffen, wie in Ländern mit eigenem nationalem Standard — EN 16931 über Peppol ist einfach der akzeptierte Ansatz, wo immer E-Rechnung freiwillig genutzt wird.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Format et norme', '[["Norme", "EN 16931, la norme européenne sur la facturation électronique"], ["Base légale", "Loi 89(I)/2019, transposant la directive européenne 2014/55/UE"], ["Format national", "Aucun — il n''existe pas de format chypriote distinct aux côtés de l''EN 16931"], ["B2B aujourd''hui", "Aucune obligation ; accord bilatéral entre partenaires commerciaux lorsqu''il est utilisé"]]', 'Il n''y a ici aucune décision de format à prendre comme dans les pays dotés de leur propre norme nationale — l''EN 16931 via Peppol est simplement l''approche acceptée partout où la facturation électronique est utilisée volontairement.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Identificadores y registro', '[["Recepción B2G", "No se necesita registro — es una obligación de los organismos públicos, no de los proveedores"], ["Emisión voluntaria", "A través de un punto de acceso Peppol, o del propio portal del gobierno"], ["Organismo regulador", "Ministerio de Hacienda"], ["B2B hoy", "No existe registro — no hay nada para lo que registrarse"]]', 'Como no existe un mandato de emisión, genuinamente no hay ningún paso de registro que una empresa típica deba completar — la obligación que Chipre ha promulgado hasta ahora se aplica enteramente al lado de la recepción.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Kennungen & Registrierung', '[["B2G-Empfang", "Keine Registrierung nötig — dies ist eine Pflicht öffentlicher Stellen, nicht der Lieferanten"], ["Freiwillige Ausstellung", "Über einen Peppol-Zugangspunkt oder das Regierungsportal selbst"], ["Aufsichtsbehörde", "Finanzministerium"], ["B2B heute", "Keine Registrierung vorhanden — es gibt nichts, wofür man sich registrieren müsste"]]', 'Da es keine Ausstellungspflicht gibt, gibt es für ein typisches Unternehmen tatsächlich keinen Registrierungsschritt zu erledigen — die bisher von Zypern erlassene Pflicht betrifft ausschließlich die Empfangsseite.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Identifiants et enregistrement', '[["Réception B2G", "Aucun enregistrement nécessaire — il s''agit d''une obligation des organismes publics, non des fournisseurs"], ["Émission volontaire", "Via un point d''accès Peppol, ou le portail du gouvernement lui-même"], ["Organisme de contrôle", "Ministère des Finances"], ["B2B aujourd''hui", "Aucun enregistrement n''existe — il n''y a rien à quoi s''inscrire"]]', 'Comme il n''existe aucune obligation d''émission, il n''y a véritablement aucune étape d''enregistrement à accomplir pour une entreprise typique — l''obligation adoptée par Chypre à ce jour s''applique entièrement du côté de la réception.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Contenido obligatorio', '[["Cuando se usa", "Modelo básico completo de EN 16931"], ["Campos obligatorios", "Ninguno especificado más allá de la propia norma, ya que no existe un mandato nacional que defina requisitos adicionales"], ["Archivo", "Se aplican los requisitos estándar chipriotas de conservación de registros"]]', 'Sin un mandato nacional que especifique campos nacionales adicionales (a diferencia, por ejemplo, del KSeF de Polonia o el SdI de Italia), una factura electrónica chipriota es simplemente un documento estándar EN 16931 — nada extra que aprender.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Pflichtinhalte', '[["Bei Verwendung", "Vollständiges EN-16931-Kernrechnungsmodell"], ["Pflichtfelder", "Keine über die Norm selbst hinaus festgelegt, da es keine inländische Pflicht gibt, die zusätzliche Anforderungen definiert"], ["Archivierung", "Es gelten die zypriotischen Standard-Aufbewahrungspflichten"]]', 'Ohne inländische Pflicht, die zusätzliche nationale Felder festlegt (anders als etwa Polens KSeF oder Italiens SdI), ist eine zypriotische E-Rechnung schlicht ein Standard-EN-16931-Dokument — nichts Zusätzliches zu lernen.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Contenu obligatoire', '[["Si utilisé", "Modèle de facture de base complet EN 16931"], ["Champs obligatoires", "Aucun spécifié au-delà de la norme elle-même, puisqu''il n''existe aucune obligation nationale définissant des exigences supplémentaires"], ["Archivage", "Les exigences standard chypriotes de conservation des documents s''appliquent"]]', 'Sans obligation nationale précisant des champs nationaux supplémentaires (contrairement, par exemple, au KSeF polonais ou au SdI italien), une facture électronique chypriote est simplement un document EN 16931 standard — rien de plus à apprendre.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'file_format' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Modelo de red', '[["Modelo", "Sin régimen de compensación ni de reporte en tiempo real de ningún tipo"], ["Canal B2G", "Red Peppol o portal del gobierno, para los proveedores que elijan enviar electrónicamente"], ["Canal B2B", "Acuerdo bilateral, si se usa"], ["Reporte en tiempo real", "Ninguno — Chipre no tiene sistema de reporte digital del IVA"]]', 'Este es uno de los modelos regulatorios más ligeros que existen en este rastreador — sin compensación, sin reporte obligatorio, y solo una obligación de recepción en un lado de un tipo de transacción.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Netzwerkmodell', '[["Modell", "Kein Clearance- oder Echtzeit-Meldungsregime jeglicher Art"], ["B2G-Kanal", "Peppol-Netzwerk oder Regierungsportal, für Lieferanten, die sich für die elektronische Übermittlung entscheiden"], ["B2B-Kanal", "Bilaterale Vereinbarung, sofern überhaupt genutzt"], ["Echtzeit-Meldung", "Keine — Zypern hat kein digitales Mehrwertsteuer-Meldesystem"]]', 'Dies ist eines der am wenigsten regulierten Modelle in diesem Tracker — kein Clearance, keine Meldepflicht, und nur eine Empfangspflicht auf einer Seite eines Transaktionstyps.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Modèle de réseau', '[["Modèle", "Aucun régime de validation préalable ou de déclaration en temps réel d''aucune sorte"], ["Canal B2G", "Réseau Peppol ou portail du gouvernement, pour les fournisseurs qui choisissent d''envoyer électroniquement"], ["Canal B2B", "Accord bilatéral, si utilisé"], ["Déclaration en temps réel", "Aucune — Chypre n''a pas de système de déclaration numérique de TVA"]]', 'C''est l''un des modèles réglementaires les plus légers de ce tracker — aucune validation préalable, aucune déclaration obligatoire, et seulement une obligation de réception d''un côté d''un type de transaction.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Lo que realmente es obligatorio hoy', '[["Organismos del gobierno central", "Deben recibir y procesar facturas electrónicas conformes (desde 2019)"], ["Todos los demás organismos públicos", "Deben recibir y procesar facturas electrónicas conformes (desde 2020)"], ["Proveedores del gobierno", "Sin obligación de emisión"], ["Empresas privadas (B2B/B2C)", "Sin obligación de ningún tipo"]]', 'Vale la pena ser precisos aquí: Chipre nunca ha exigido realmente que nadie envíe una factura electrónica — solo que ciertos organismos públicos sean capaces de aceptar una si un proveedor decide enviarla.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Was heute tatsächlich verpflichtend ist', '[["Zentrale Regierungsstellen", "Müssen konforme E-Rechnungen empfangen und verarbeiten können (seit 2019)"], ["Alle übrigen öffentlichen Stellen", "Müssen konforme E-Rechnungen empfangen und verarbeiten können (seit 2020)"], ["Lieferanten an die Regierung", "Keine Ausstellungspflicht"], ["Private Unternehmen (B2B/B2C)", "Keine Pflicht jeglicher Art"]]', 'Es lohnt sich, hier präzise zu sein: Zypern hat nie tatsächlich vorgeschrieben, dass jemand eine E-Rechnung versendet — nur, dass bestimmte öffentliche Stellen in der Lage sein müssen, eine anzunehmen, falls sich ein Lieferant dafür entscheidet.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Ce qui est réellement obligatoire aujourd''hui', '[["Organismes du gouvernement central", "Doivent recevoir et traiter des factures électroniques conformes (depuis 2019)"], ["Tous les autres organismes publics", "Doivent recevoir et traiter des factures électroniques conformes (depuis 2020)"], ["Fournisseurs du gouvernement", "Aucune obligation d''émission"], ["Entreprises privées (B2B/B2C)", "Aucune obligation d''aucune sorte"]]', 'Il convient d''être précis à ce sujet : Chypre n''a jamais réellement imposé à quiconque d''envoyer une facture électronique — seulement que certains organismes publics soient capables d''en accepter une si un fournisseur choisit de le faire.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', 'Un patrón de mandatos discutidos pero abandonados', '[["Objetivo de 2022", "Emisión B2G obligatoria discutida por el Ministerio de Hacienda, prevista para el 1 de enero de 2022 — nunca promulgada"], ["Objetivo de 2024", "Un impulso similar, vinculado a la implementación de un ERP — también pospuesto indefinidamente"], ["Estado actual", "Sin calendario nacional confirmado ni para la emisión B2G ni para el B2B, en el momento de redactar esto"], ["Suelo firme en cualquier caso", "1 de julio de 2030 — B2B transfronterizo de ViDA, derecho de la UE confirmado"]]', 'Esta es la única entrada de esta página que merece la pena vigilar en busca de una señal real — Chipre ha propuesto fechas de mandato dos veces antes sin cumplirlas, así que lo apropiado es seguir las fuentes oficiales en busca de un paso legislativo genuino, no solo otra discusión.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', 'Ein Muster diskutierter, aber aufgegebener Pflichten', '[["Ziel 2022", "Verpflichtende B2G-Ausstellung, vom Finanzministerium diskutiert, geplant für den 1. Januar 2022 — nie umgesetzt"], ["Ziel 2024", "Ein ähnlicher Vorstoß, gekoppelt an eine ERP-Einführung — ebenfalls auf unbestimmte Zeit verschoben"], ["Aktueller Status", "Kein bestätigter inländischer Zeitplan weder für die B2G-Ausstellung noch für B2B, Stand dieser Abfassung"], ["Feste Untergrenze in jedem Fall", "1. Juli 2030 — grenzüberschreitendes B2B nach ViDA, bestätigtes EU-Recht"]]', 'Dies ist der einzige Eintrag auf dieser Seite, der ein echtes Signal wert ist, es zu beobachten — Zypern hat bereits zweimal Pflichttermine in Aussicht gestellt, ohne sie einzuhalten, daher ist es angebracht, offizielle Quellen auf einen echten Gesetzgebungsschritt zu verfolgen, nicht nur eine weitere Diskussion.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', 'Un schéma d''obligations discutées mais abandonnées', '[["Objectif 2022", "Émission B2G obligatoire discutée par le ministère des Finances, prévue pour le 1er janvier 2022 — jamais adoptée"], ["Objectif 2024", "Une initiative similaire, liée à la mise en œuvre d''un ERP — également reportée indéfiniment"], ["Statut actuel", "Aucun calendrier national confirmé ni pour l''émission B2G ni pour le B2B, au moment de la rédaction"], ["Plancher ferme dans tous les cas", "1er juillet 2030 — B2B transfrontalier ViDA, droit de l''UE confirmé"]]', 'C''est la seule entrée de cette page qui mérite d''être surveillée pour un véritable signal — Chypre a déjà proposé deux fois des dates d''obligation sans les tenir, l''attitude appropriée est donc de suivre les sources officielles pour une véritable étape législative, pas simplement une nouvelle discussion.', NULL FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'scope_transmission' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🤝 Sin régimen sancionador, porque no hay mandato', NULL, NULL, 'No existe una sanción nacional por no emitir una factura electrónica en Chipre hoy, por la sencilla razón de que ninguna ley lo exige. La única obligación exigible — recibir facturas conformes — recae en los organismos públicos, no en los proveedores.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🤝 Kein Sanktionsregime, weil keine Pflicht', NULL, NULL, 'Es gibt heute keine inländische Strafe für die Nichtausstellung einer E-Rechnung in Zypern, aus dem einfachen Grund, dass kein Gesetz dies verlangt. Die einzige durchsetzbare Pflicht — konforme Rechnungen zu empfangen — liegt bei öffentlichen Stellen, nicht bei Lieferanten.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🤝 Aucun régime de sanctions, car aucune obligation', NULL, NULL, 'Il n''existe aujourd''hui aucune sanction nationale pour non-émission d''une facture électronique à Chypre, pour la simple raison qu''aucune loi ne l''exige. La seule obligation exécutoire — recevoir des factures conformes — incombe aux organismes publics, non aux fournisseurs.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '📋 Propuesto dos veces, abandonado dos veces', NULL, NULL, 'Tanto el objetivo de 2022 como el de 2024 para la emisión B2G obligatoria fueron propuestas genuinas del Ministerio de Hacienda, no rumores — pero ninguno se tradujo en legislación real. Vale la pena recordarlo si surge un futuro anuncio: Chipre tiene un historial de proponer fechas que no cumple.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '📋 Zweimal vorgeschlagen, zweimal fallengelassen', NULL, NULL, 'Sowohl das Ziel für 2022 als auch für 2024 zur verpflichtenden B2G-Ausstellung waren echte Vorschläge des Finanzministeriums, keine Gerüchte — aber keines wurde je in tatsächliche Gesetzgebung umgesetzt. Es lohnt sich, das im Hinterkopf zu behalten, falls eine künftige Ankündigung auftaucht: Zypern hat eine Geschichte, Termine vorzuschlagen, die es nicht einhält.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '📋 Proposé deux fois, abandonné deux fois', NULL, NULL, 'Les objectifs de 2022 et de 2024 pour l''émission B2G obligatoire étaient de véritables propositions du ministère des Finances, pas des rumeurs — mais aucun n''a été suivi d''une véritable législation. Bon à se rappeler si une future annonce fait surface : Chypre a un historique de propositions de dates qu''elle ne tient pas.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'es', '🇪🇺 El suelo de la UE que se acerca', NULL, NULL, 'Con independencia de si Chipre llega a promulgar su propio mandato nacional, el requisito transfronterizo de ViDA es derecho de la UE confirmado desde el 1 de julio de 2030 — toda empresa chipriota que realice comercio B2B intracomunitario necesitará facturación electrónica y reporte digital conformes con EN 16931 para esas transacciones.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'de', '🇪🇺 Die näherrückende EU-Untergrenze', NULL, NULL, 'Unabhängig davon, ob Zypern jemals eine eigene inländische Pflicht erlässt, ist die grenzüberschreitende ViDA-Anforderung ab dem 1. Juli 2030 bestätigtes EU-Recht — jedes zypriotische Unternehmen mit innergemeinschaftlichem B2B-Handel wird für diese Umsätze EN-16931-konforme E-Rechnung und digitale Meldung benötigen.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_card_translations (card_id, lang, title, rows_json, note, body) SELECT dc.id, 'fr', '🇪🇺 Le plancher de l''UE qui approche', NULL, NULL, 'Que Chypre finisse ou non par adopter sa propre obligation nationale, l''exigence transfrontalière de ViDA est un droit de l''UE confirmé à partir du 1er juillet 2030 — toute entreprise chypriote réalisant du commerce B2B intracommunautaire aura besoin d''une facturation électronique et d''une déclaration numérique conformes à l''EN 16931 pour ces transactions.' FROM deep_dive_cards dc JOIN countries c ON c.id = dc.country_id WHERE c.name_en = 'Cyprus' AND dc.section = 'penalties_related' AND dc.sort_order = 2;

INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Entienda lo que realmente es obligatorio (muy poco)', 'Solo se exige por ley la capacidad de recepción de los organismos públicos — no hay obligación de emisión para los proveedores, ni ningún mandato B2B hoy en día.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Verstehen Sie, was tatsächlich verpflichtend ist (sehr wenig)', 'Gesetzlich ist nur die Empfangsfähigkeit öffentlicher Stellen vorgeschrieben — es gibt keine Ausstellungspflicht für Lieferanten und heute keine B2B-Pflicht jeglicher Art.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Comprenez ce qui est réellement obligatoire (très peu)', 'Seule la capacité de réception des organismes publics est exigée par la loi — il n''y a aucune obligation d''émission pour les fournisseurs, ni aucune obligation B2B aujourd''hui.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 0;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Si abastece a organismos públicos chipriotas, considere la facturación electrónica voluntaria', 'Enviar facturas electrónicas estructuradas a través de Peppol puede acelerar el procesamiento aunque no sea obligatorio — una forma de bajo coste de adelantarse a un futuro mandato.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Wenn Sie zypriotische öffentliche Stellen beliefern, erwägen Sie freiwillige E-Rechnung', 'Der Versand strukturierter E-Rechnungen über Peppol kann die Bearbeitung beschleunigen, obwohl es nicht vorgeschrieben ist — eine kostengünstige Möglichkeit, einer künftigen Pflicht voraus zu sein.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Si vous fournissez des organismes publics chypriotes, envisagez la facturation électronique volontaire', 'L''envoi de factures électroniques structurées via Peppol peut accélérer le traitement même si ce n''est pas requis — un moyen peu coûteux de prendre de l''avance sur une future obligation.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 1;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'No invierta en exceso en seguir una fecha nacional concreta', 'Chipre ha propuesto fechas de mandato dos veces antes (2022, 2024) sin promulgar ninguna — trate cualquier futuro anuncio con la debida cautela hasta que esté genuinamente confirmado por ley.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Investieren Sie nicht zu viel in die Verfolgung eines konkreten inländischen Termins', 'Zypern hat bereits zweimal Pflichttermine vorgeschlagen (2022, 2024), ohne einen davon umzusetzen — behandeln Sie jede künftige Ankündigung mit angemessener Vorsicht, bis sie tatsächlich gesetzlich bestätigt ist.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'N''investissez pas trop dans le suivi d''une date nationale précise', 'Chypre a déjà proposé deux fois des dates d''obligation (2022, 2024) sans en adopter aucune — traitez toute future annonce avec la prudence appropriée jusqu''à ce qu''elle soit véritablement confirmée par la loi.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 2;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Prepárese para el suelo transfronterizo de 2030 en cualquier caso', 'Toda empresa que realice comercio B2B intracomunitario necesita capacidad de facturación electrónica EN 16931 y reporte digital desde el 1 de julio de 2030 — esta fecha la fija la directiva de la UE, no la discreción chipriota.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Bereiten Sie sich in jedem Fall auf die bestätigte grenzüberschreitende Untergrenze 2030 vor', 'Jedes Unternehmen mit innergemeinschaftlichem B2B-Handel benötigt ab dem 1. Juli 2030 EN-16931-E-Rechnungs- und digitale Meldefähigkeit — dieses Datum ist durch EU-Richtlinie festgelegt, nicht durch zypriotisches Ermessen.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Préparez-vous au plancher transfrontalier de 2030 dans tous les cas', 'Toute entreprise réalisant du commerce B2B intracommunautaire a besoin d''une capacité de facturation électronique EN 16931 et de déclaration numérique dès le 1er juillet 2030 — cette date est fixée par la directive de l''UE, non par la discrétion chypriote.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 3;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'es', 'Vigile las fuentes oficiales, no los comentarios de asesores, para la señal real', 'Dado el patrón de objetivos discutidos pero abandonados, los propios anuncios del Ministerio de Hacienda son el único indicador fiable de que algo ha cambiado realmente.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'de', 'Beobachten Sie offizielle Quellen, nicht Beraterkommentare, für das echte Signal', 'Angesichts des Musters diskutierter, aber aufgegebener Ziele sind die eigenen Ankündigungen des Finanzministeriums der einzige verlässliche Indikator dafür, dass sich tatsächlich etwas geändert hat.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 4;
INSERT OR IGNORE INTO deep_dive_step_translations (step_id, lang, title, description) SELECT ds.id, 'fr', 'Surveillez les sources officielles, pas les commentaires d''experts, pour le véritable signal', 'Compte tenu du schéma d''objectifs discutés mais abandonnés, les propres annonces du ministère des Finances sont le seul indicateur fiable qu''un changement réel s''est produit.' FROM deep_dive_steps ds JOIN countries c ON c.id = ds.country_id WHERE c.name_en = 'Cyprus' AND ds.sort_order = 4;

